def enqueue(q, item):
    q.append(item)

def dequeue(q):
    if len(q) == 0:
        return "Underflow"
    return q.pop(0)

def peek(q):
    if len(q) == 0:
        return "Queue empty"
    return q[0]

def isEmpty(q):
    return len(q) == 0
```

